import torch
from torch import nn

class Demo(nn.Module):
    def __init__(self):
        super().__init__()
        self.scale = nn.Parameter(torch.ones(3))
        self.layer = nn.Linear(3, 2)
        self.register_buffer("mean", torch.zeros(3))
        self.forgotten = [nn.Linear(2, 2)]

    def forward(self, x):
        return self.forgotten[0](self.layer((x - self.mean) * self.scale))

