import torch
from torch import nn

class Net(nn.Module):
    def __init__(self):
        super().__init__()
        self.fc1, self.fc2 = nn.Linear(4, 8), nn.Linear(8, 2)

    def forward(self, x):
        return self.fc2(torch.relu(self.fc1(x)))

torch.manual_seed(0)
model = Net().eval()
batch = torch.export.Dim("batch")
program = torch.export.export(model, (torch.randn(4, 4),), dynamic_shapes={"x": {0: batch}})
print([str(n.target) for n in program.graph.nodes if n.op == "call_function"])

